# 50-question SQL-agent benchmark (manager perspective), mixed difficulty.
# Cluster titles reflect the current DB run:
#   -1 Complex High Need | 0 Kids and Well | 1 Everyday Care
#    2 Many Chronic Illnesses | 3 Pregnancy Care

QUERIES = [
    # ---------- Simple (single table) ----------
    {"question": "How many patients are in the database?",
     "sql": "SELECT COUNT(*) AS n FROM patient"},
    {"question": "What is the average age of the patients?",
     "sql": "SELECT ROUND(AVG(age)::numeric, 1) AS avg_age FROM patient"},
    {"question": "How many patients have died?",
     "sql": "SELECT COUNT(*) AS n FROM patient WHERE deathdate IS NOT NULL"},
    {"question": "How many patients identify as black race?",
     "sql": "SELECT COUNT(*) AS n FROM patient WHERE race = 'black'"},
    {"question": "Which city has the most patients?",
     "sql": "SELECT city, COUNT(*) AS n FROM patient GROUP BY city ORDER BY n DESC LIMIT 1"},
    {"question": "How many female patients are there?",
     "sql": "SELECT COUNT(*) AS n FROM patient WHERE gender = 'F'"},
    {"question": "What is the age of the oldest patient in the database?",
     "sql": "SELECT MAX(age) AS max_age FROM patient"},
    {"question": "How many encounters are classified as emergency?",
     "sql": "SELECT COUNT(*) AS n FROM encounter WHERE encounter_class = 'emergency'"},
    {"question": "How many care plans have been recorded in total?",
     "sql": "SELECT COUNT(*) AS n FROM careplan"},
    {"question": "How many providers work at the hospital?",
     "sql": "SELECT COUNT(*) AS n FROM provider"},
    {"question": "What is the most common condition recorded in the database?",
     "sql": "SELECT description, COUNT(*) AS n FROM condition GROUP BY description ORDER BY n DESC LIMIT 1"},
    {"question": "What is the most frequently prescribed medication?",
     "sql": "SELECT description, COUNT(*) AS n FROM medication GROUP BY description ORDER BY n DESC LIMIT 1"},
    {"question": "What is the most common procedure performed?",
     "sql": "SELECT description, COUNT(*) AS n FROM procedure GROUP BY description ORDER BY n DESC LIMIT 1"},
    {"question": "How many distinct patients underwent renal dialysis?",
     "sql": "SELECT COUNT(DISTINCT patient_id) AS n FROM procedure WHERE description = 'Renal dialysis (procedure)'"},
    {"question": "What is the highest heart rate ever recorded in the observations?",
     "sql": "SELECT MAX(value_numeric) AS max_hr FROM observation WHERE description = 'Heart rate'"},

    # ---------- Medium (filters, subqueries, ratios) ----------
    {"question": "How many patients are older than 70?",
     "sql": "SELECT COUNT(*) AS n FROM patient WHERE age > 70"},
    {"question": "How many distinct patients have more than 20 condition records each?",
     "sql": "SELECT COUNT(*) AS n FROM (SELECT patient_id FROM condition GROUP BY patient_id HAVING COUNT(*) > 20) t"},
    {"question": "How many patients have no recorded allergies at all?",
     "sql": "SELECT COUNT(*) AS n FROM patient WHERE patient_id NOT IN (SELECT DISTINCT patient_id FROM allergy)"},
    {"question": "What is the average systolic blood pressure recorded across all observations?",
     "sql": "SELECT ROUND(AVG(value_numeric)::numeric, 1) AS avg_sbp FROM observation WHERE description = 'Systolic Blood Pressure'"},
    {"question": "How many distinct patients have at least one BMI observation showing obesity (30 or above)?",
     "sql": "SELECT COUNT(DISTINCT patient_id) AS n FROM observation WHERE description = 'Body mass index (BMI) [Ratio]' AND value_numeric >= 30"},
    {"question": "What is the average duration, in hours, of inpatient encounters?",
     "sql": "SELECT ROUND((AVG(duration) / 60.0)::numeric, 2) AS avg_hours FROM encounter WHERE encounter_class = 'inpatient'"},
    {"question": "How many encounters took place in 2020?",
     "sql": "SELECT COUNT(*) AS n FROM encounter WHERE EXTRACT(YEAR FROM start_date) = 2020"},
    {"question": "How many male patients living in Houston are there?",
     "sql": "SELECT COUNT(*) AS n FROM patient WHERE city = 'Houston' AND gender = 'M'"},
    {"question": "What is the average number of medication records per patient?",
     "sql": "SELECT ROUND((SELECT COUNT(*)::numeric FROM medication) / (SELECT COUNT(DISTINCT patient_id)::numeric FROM medication), 2) AS avg_meds"},
    {"question": "How many distinct patients are prescribed lisinopril 10 MG Oral Tablet?",
     "sql": "SELECT COUNT(DISTINCT patient_id) AS n FROM medication WHERE description = 'lisinopril 10 MG Oral Tablet'"},
    {"question": "How many distinct patients received a 30 mcg mRNA COVID-19 vaccine dose?",
     "sql": "SELECT COUNT(DISTINCT patient_id) AS n FROM immunization WHERE description = 'COVID-19  mRNA  LNP-S  PF  30 mcg/0.3 mL dose'"},
    {"question": "What is the average duration in days of care plans that have already ended?",
     "sql": "SELECT ROUND(AVG(duration_days)::numeric, 1) AS avg_days FROM careplan WHERE end_date IS NOT NULL"},
    {"question": "How many patients had more than one inpatient encounter?",
     "sql": "SELECT COUNT(*) AS n FROM (SELECT patient_id FROM encounter WHERE encounter_class = 'inpatient' GROUP BY patient_id HAVING COUNT(*) > 1) t"},
    {"question": "What is the name of the hospital organization in the database?",
     "sql": "SELECT name FROM organization LIMIT 1"},

    # ---------- Complex (cross-table joins, provider/cluster analytics) ----------
    {"question": "Which patient has the highest number of encounters, and how many?",
     "sql": "SELECT p.first_name, p.last_name, t.n FROM (SELECT patient_id, COUNT(*) AS n FROM encounter GROUP BY patient_id ORDER BY n DESC LIMIT 1) t JOIN patient p ON p.patient_id = t.patient_id"},
    {"question": "Which medical speciality performed the most procedures, and how many?",
     "sql": "SELECT pr.speciality, COUNT(*) AS n FROM procedure pc JOIN encounter e ON e.encounter_id = pc.encounter_id JOIN provider pr ON pr.provider_id = e.provider_id GROUP BY pr.speciality ORDER BY n DESC LIMIT 1"},
    {"question": "Which provider has seen the most distinct patients, and how many?",
     "sql": "SELECT pr.first_name, pr.last_name, COUNT(DISTINCT e.patient_id) AS n FROM encounter e JOIN provider pr ON pr.provider_id = e.provider_id GROUP BY pr.provider_id, pr.first_name, pr.last_name ORDER BY n DESC LIMIT 1"},
    {"question": "Which provider handled the most emergency encounters, and how many?",
     "sql": "SELECT pr.first_name, pr.last_name, COUNT(*) AS n FROM encounter e JOIN provider pr ON pr.provider_id = e.provider_id WHERE e.encounter_class = 'emergency' GROUP BY pr.provider_id, pr.first_name, pr.last_name ORDER BY n DESC LIMIT 1"},
    {"question": "Which speciality prescribed the most medications, and how many?",
     "sql": "SELECT pr.speciality, COUNT(*) AS n FROM medication m JOIN encounter e ON e.encounter_id = m.encounter_id JOIN provider pr ON pr.provider_id = e.provider_id GROUP BY pr.speciality ORDER BY n DESC LIMIT 1"},
    {"question": "Which speciality has the longest average encounter duration, in minutes?",
     "sql": "SELECT pr.speciality, ROUND(AVG(e.duration)::numeric, 1) AS avg_min FROM encounter e JOIN provider pr ON pr.provider_id = e.provider_id GROUP BY pr.speciality ORDER BY avg_min DESC LIMIT 1"},
    {"question": "Which speciality has seen the most distinct patients, and how many?",
     "sql": "SELECT pr.speciality, COUNT(DISTINCT e.patient_id) AS n FROM encounter e JOIN provider pr ON pr.provider_id = e.provider_id GROUP BY pr.speciality ORDER BY n DESC LIMIT 1"},
    {"question": "What is the most common procedure performed during inpatient encounters?",
     "sql": "SELECT pc.description, COUNT(*) AS n FROM procedure pc JOIN encounter e ON e.encounter_id = pc.encounter_id WHERE e.encounter_class = 'inpatient' GROUP BY pc.description ORDER BY n DESC LIMIT 1"},
    {"question": "What is the most common condition recorded during emergency encounters?",
     "sql": "SELECT co.description, COUNT(*) AS n FROM condition co JOIN encounter e ON e.encounter_id = co.encounter_id WHERE e.encounter_class = 'emergency' GROUP BY co.description ORDER BY n DESC LIMIT 1"},
    {"question": "How many patients were readmitted to inpatient care within 30 days of a previous inpatient discharge?",
     "sql": "SELECT COUNT(DISTINCT e1.patient_id) AS n FROM encounter e1 JOIN encounter e2 ON e2.patient_id = e1.patient_id WHERE e1.encounter_class = 'inpatient' AND e2.encounter_class = 'inpatient' AND e2.start_date > e1.end_date AND e2.start_date <= e1.end_date + INTERVAL '30 days'"},
    {"question": "How many distinct patients take both lisinopril 10 MG Oral Tablet and Hydrochlorothiazide 25 MG Oral Tablet?",
     "sql": "SELECT COUNT(*) AS n FROM (SELECT patient_id FROM medication WHERE description = 'lisinopril 10 MG Oral Tablet' INTERSECT SELECT patient_id FROM medication WHERE description = 'Hydrochlorothiazide 25 MG Oral Tablet') t"},
    {"question": "How many distinct patients have both a Viral sinusitis condition and take Acetaminophen 325 MG Oral Tablet?",
     "sql": "SELECT COUNT(*) AS n FROM (SELECT patient_id FROM condition WHERE description = 'Viral sinusitis (disorder)' INTERSECT SELECT patient_id FROM medication WHERE description = 'Acetaminophen 325 MG Oral Tablet [Tylenol]') t"},
    {"question": "How many patients over the age of 65 have been prescribed lisinopril 10 MG Oral Tablet?",
     "sql": "SELECT COUNT(DISTINCT p.patient_id) AS n FROM patient p JOIN medication m ON m.patient_id = p.patient_id WHERE p.age > 65 AND m.description = 'lisinopril 10 MG Oral Tablet'"},
    {"question": "What is the average age of patients in the 'Many Chronic Illnesses' cluster?",
     "sql": "SELECT ROUND(AVG(p.age)::numeric, 1) AS avg_age FROM cluster_patient cp JOIN patient p ON p.patient_id = cp.patient_id JOIN cluster c ON c.cluster_label = cp.cluster_label WHERE c.title = 'Many Chronic Illnesses'"},
    {"question": "Which cluster has the highest average number of inpatient encounters per patient?",
     "sql": "SELECT c.title, ROUND(AVG(t.cnt)::numeric, 2) AS avg_ip FROM (SELECT cp.patient_id, cp.cluster_label, COUNT(e.encounter_id) AS cnt FROM cluster_patient cp LEFT JOIN encounter e ON e.patient_id = cp.patient_id AND e.encounter_class = 'inpatient' GROUP BY cp.patient_id, cp.cluster_label) t JOIN cluster c ON c.cluster_label = t.cluster_label GROUP BY c.title ORDER BY avg_ip DESC LIMIT 1"},
    {"question": "How many patients in the 'Complex High Need' outlier cluster have had at least one emergency encounter?",
     "sql": "SELECT COUNT(DISTINCT cp.patient_id) AS n FROM cluster_patient cp JOIN encounter e ON e.patient_id = cp.patient_id JOIN cluster c ON c.cluster_label = cp.cluster_label WHERE c.title = 'Complex High Need' AND e.encounter_class = 'emergency'"},
    {"question": "What is the most common medication prescribed to patients in the 'Complex High Need' outlier cluster?",
     "sql": "SELECT m.description, COUNT(*) AS n FROM medication m JOIN cluster_patient cp ON cp.patient_id = m.patient_id JOIN cluster c ON c.cluster_label = cp.cluster_label WHERE c.title = 'Complex High Need' GROUP BY m.description ORDER BY n DESC LIMIT 1"},
    {"question": "Which cluster has the most patients assigned to it?",
     "sql": "SELECT c.title, t.n FROM (SELECT cluster_label, COUNT(*) AS n FROM cluster_patient GROUP BY cluster_label ORDER BY n DESC LIMIT 1) t JOIN cluster c ON c.cluster_label = t.cluster_label"},
    {"question": "How many patient clusters were identified by the clustering pipeline, including the outlier group?",
     "sql": "SELECT COUNT(DISTINCT cluster_label) AS n FROM cluster"},
    {"question": "What is the most frequent global care sequence pattern that was mined?",
     "sql": "SELECT pattern_str, support_count FROM prefix_span_pattern WHERE cluster_label IS NULL ORDER BY support_count DESC LIMIT 1"},
    {"question": "How many sequence patterns were mined specifically for cluster 0?",
     "sql": "SELECT COUNT(*) AS n FROM prefix_span_pattern WHERE cluster_label = 0"},
]

assert len(QUERIES) == 50, len(QUERIES)
